def prepare():
    import hashlib, importlib, importlib.util, sys
    from pathlib import Path
    package='glm_reconstruction_v12_helpers'
    root=Path('/home/matteius/experiments/glm-reconstruction-20261006/build-native-fused-v12/glm_reconstruction_v12_helpers')
    if package not in sys.modules:
        spec=importlib.util.spec_from_file_location(package,root/'__init__.py',submodule_search_locations=[str(root)])
        module=importlib.util.module_from_spec(spec)
        sys.modules[package]=module
        spec.loader.exec_module(module)
    if Path(sys.modules[package].__file__).resolve() != (root/'__init__.py').resolve():
        raise ValueError('fused helper package belongs to another build')
    for name, expected in {'glm_fused_moe.py': 'e75cf970dd7cafbbd648d9c50768c7cefd6585b155910b5184cb629d2aeba813', 'reconstruction_probe.py': '53671a4e566771d23f945d55037e24cc7120df8a7d21672802b5a5e2724f3d83', 'fused_moe_probe.py': 'e9c73b6bc5eb444782d6e72f5c6af7e3bf66c6fd024dca77768d9e9e598a8d98', 'expert_reconstruction.py': 'c4bdbb69345ae38d507688115d435a5a6414e638a68abe008e0fe52a015c9f20', 'glm_int4.py': 'be71985a4fd66c3f99d950abb5da4f8383ad607c421c8b3bfbe1ec3564e0a843', '__init__.py': '6c6ec57de9f82ef42d82760f144a4571cb16b3cd6de33aaa7aa9fd65e8ab1fa1', 'reconstruction_native.py': '9bf814f721c063009c3e211841a55f7940c849c99d018d0822227f1cc3f5752c'}.items():
        if hashlib.sha256((root/name).read_bytes()).hexdigest()!=expected:
            raise ValueError('fused helper changed: '+name)
    from glm_reconstruction_v12_helpers.glm_fused_moe import NativeFusedMoE
    return {'fused_int4a'+str(bits): NativeFusedMoE(Path('/home/matteius/experiments/glm-reconstruction-20261006/build-native-fused-v12'),namespace='glm_reconstruction_v12',activation_bits=bits)
            for bits in (8,4)}

def validate(resources):
    from glm_reconstruction_v12_helpers.fused_moe_probe import gate_case
    records=[gate_case(native,bits) for native in resources.values() for bits in (2,3,4)]
    return {'passed':True,'cases':len(records),'native_fused_stages':2,
             'fp16_intermediate_gm_bytes':0,'model_quality':'not_evaluated'}
